with source as (
  select id,slug from public.content_entries where content_type='legal' and locale='tr' and slug in ('about','returns','privacy','terms') and deleted_at is null
), drafts(locale,slug,title,summary,body_markdown,body_html) as (
 values
 ('en','about','About Golden Oremar','Draft English translation describing Golden Oremar, producer verification and marketplace transparency.','# About Golden Oremar\n\nGolden Oremar is a marketplace designed to connect village and local producers with customers while preserving transparent product, origin, stock and seller information. Product images, organic or certification claims, shipping data and other trust signals must be backed by real records.\n\nThis English version is a working translation of the Turkish legal content. It must be reviewed against the final registered business identity before being published as the controlling legal text.','<h1>About Golden Oremar</h1><p>Golden Oremar connects village and local producers with customers while requiring transparent, verifiable product and seller information.</p><p>This English text is a draft translation and requires final legal review.</p>'),
 ('en','returns','Returns, Withdrawal and Problem Products','Draft English return and withdrawal policy including perishable-goods exceptions and defective-item rights.','# Returns, Withdrawal and Problem Products\n\nWhere no statutory exception applies, consumers may use the applicable withdrawal right for distance sales. Perishable goods, short shelf-life foods and certain opened hygiene-sensitive products may be subject to legal exceptions. These exceptions do not remove rights relating to defective, damaged, incomplete or incorrect goods.\n\nThis is a draft English translation and must be legally reviewed before publication.','<h1>Returns and Withdrawal</h1><p>Applicable consumer withdrawal rights and lawful exceptions for perishable or hygiene-sensitive products are respected. Defective-item rights remain protected.</p><p>Draft translation, legal review required.</p>'),
 ('en','privacy','Privacy and Personal Data Notice','Draft English privacy notice covering account, order, payment, support, security and producer-verification data.','# Privacy and Personal Data Notice\n\nGolden Oremar may process account, contact, delivery, order, payment-reference, support, security, notification and producer-application data for service delivery, legal obligations, fraud prevention and rights management. Raw card data is not intended to be stored in the Golden Oremar database.\n\nThe final data-controller identity, registered address and cross-border transfer safeguards must be reviewed before this translation is published.','<h1>Privacy and Personal Data</h1><p>Golden Oremar processes only the data needed for marketplace operations, legal obligations and security.</p><p>This English version remains a draft pending final legal review.</p>'),
 ('en','terms','Golden Oremar Marketplace Terms','Draft English marketplace terms covering seller roles, product truth, orders, payments, delivery and returns.','# Golden Oremar Marketplace Terms\n\nGolden Oremar may host products sold by independent producers and by the official Golden Oremar store. Seller identity, product data, stock, price, origin, shipping requirements and special claims must come from validated backend records. Payment and payout records must remain traceable and must not create duplicate settlement.\n\nThis English version is a draft translation and requires final legal review.','<h1>Golden Oremar Marketplace Terms</h1><p>Seller identity, product truth, payment, delivery and return rules are governed by validated marketplace records and applicable law.</p><p>Draft translation, legal review required.</p>'),
 ('de','about','Über Golden Oremar','Deutscher Entwurf zu Golden Oremar, Produzentenprüfung und transparenter Marktplatzinformation.','# Über Golden Oremar\n\nGolden Oremar ist ein Marktplatz, der Dorf- und Regionalproduzenten mit Kundinnen und Kunden verbindet. Herkunft, Produzent, Bestand, Preis, Versanddaten sowie Bio- oder Zertifizierungsangaben dürfen nur angezeigt werden, wenn dafür reale und überprüfbare Informationen vorliegen.\n\nDiese deutsche Fassung ist eine Arbeitsübersetzung des türkischen Ausgangstextes und muss vor Veröffentlichung rechtlich geprüft werden.','<h1>Über Golden Oremar</h1><p>Golden Oremar verbindet lokale Produzenten mit Kunden und verlangt nachvollziehbare Produkt- und Verkäuferinformationen.</p><p>Diese Übersetzung ist ein Entwurf und benötigt eine rechtliche Prüfung.</p>'),
 ('de','returns','Rückgabe, Widerruf und mangelhafte Produkte','Deutscher Entwurf zu Widerruf, verderblichen Waren und Rechten bei mangelhaften Produkten.','# Rückgabe, Widerruf und mangelhafte Produkte\n\nSoweit keine gesetzliche Ausnahme gilt, gelten bei Fernabsatzgeschäften die einschlägigen Widerrufsrechte. Für schnell verderbliche Waren, Lebensmittel mit kurzer Haltbarkeit oder bestimmte geöffnete Hygieneprodukte können gesetzliche Ausnahmen bestehen. Rechte bei falschen, beschädigten, unvollständigen oder mangelhaften Waren bleiben davon unberührt.\n\nDiese Fassung ist ein Übersetzungsentwurf und muss vor Veröffentlichung geprüft werden.','<h1>Rückgabe und Widerruf</h1><p>Gesetzliche Widerrufsrechte und zulässige Ausnahmen für verderbliche Waren werden berücksichtigt. Mängelrechte bleiben bestehen.</p><p>Entwurf, rechtliche Prüfung erforderlich.</p>'),
 ('de','privacy','Datenschutz und Verarbeitung personenbezogener Daten','Deutscher Datenschutzentwurf für Konto-, Bestell-, Zahlungs-, Support- und Sicherheitsdaten.','# Datenschutz und Verarbeitung personenbezogener Daten\n\nGolden Oremar kann Konto-, Kontakt-, Liefer-, Bestell-, Zahlungsreferenz-, Support-, Sicherheits-, Benachrichtigungs- und Produzentenbewerbungsdaten verarbeiten, soweit dies für Vertragserfüllung, gesetzliche Pflichten, Betrugsprävention und Rechteverwaltung erforderlich ist. Offene Kartendaten sollen nicht in der Golden-Oremar-Datenbank gespeichert werden.\n\nDie endgültige Verantwortlichenidentität und Übermittlungsgrundlagen müssen vor Veröffentlichung geprüft werden.','<h1>Datenschutz</h1><p>Golden Oremar verarbeitet Daten für Marktplatzbetrieb, gesetzliche Pflichten und Sicherheit.</p><p>Diese deutsche Version ist ein Entwurf und benötigt eine abschließende rechtliche Prüfung.</p>'),
 ('de','terms','Golden Oremar Nutzungs- und Marktplatzbedingungen','Deutscher Entwurf zu Verkäuferrollen, Produktangaben, Bestellung, Zahlung, Lieferung und Rückgabe.','# Golden Oremar Nutzungs- und Marktplatzbedingungen\n\nAuf Golden Oremar können unabhängige Produzenten und der offizielle Golden-Oremar-Shop verkaufen. Verkäuferidentität, Produktdaten, Bestand, Preis, Herkunft, Versandanforderungen und besondere Qualitätsangaben müssen aus validierten Systemdaten stammen. Zahlungs- und Auszahlungsdaten müssen nachvollziehbar bleiben und Doppelzahlungen verhindern.\n\nDiese Übersetzung ist ein Entwurf und muss vor Veröffentlichung rechtlich geprüft werden.','<h1>Golden Oremar Bedingungen</h1><p>Verkäuferidentität, Produktwahrheit, Zahlung, Lieferung und Rückgabe folgen validierten Marktplatzdaten und geltendem Recht.</p><p>Entwurf, rechtliche Prüfung erforderlich.</p>'),
 ('fr','about','À propos de Golden Oremar','Projet de traduction française présentant Golden Oremar, la vérification des producteurs et la transparence du marché.','# À propos de Golden Oremar\n\nGolden Oremar est une place de marché destinée à rapprocher les producteurs villageois et locaux des clients tout en conservant des informations transparentes sur le produit, son origine, le vendeur, le stock et la livraison. Les mentions bio, certificats et autres éléments de confiance ne doivent être affichés que s ils reposent sur des données réelles et vérifiables.\n\nCette version française est un projet de traduction et doit être validée juridiquement avant publication.','<h1>À propos de Golden Oremar</h1><p>Golden Oremar relie les producteurs locaux aux clients avec des informations produit et vendeur vérifiables.</p><p>Cette traduction est un projet soumis à validation juridique.</p>'),
 ('fr','returns','Retours, rétractation et produits défectueux','Projet français sur la rétractation, les exceptions pour denrées périssables et les droits en cas de défaut.','# Retours, rétractation et produits défectueux\n\nLorsque aucune exception légale ne s applique, les droits de rétractation applicables aux ventes à distance sont respectés. Des exceptions peuvent concerner les denrées rapidement périssables, les produits à durée de conservation courte ou certains produits d hygiène ouverts. Ces exceptions ne suppriment pas les droits relatifs aux produits erronés, endommagés, incomplets ou défectueux.\n\nCe texte est un projet de traduction et doit être vérifié avant publication.','<h1>Retours et rétractation</h1><p>Les droits légaux de rétractation et les exceptions autorisées pour les produits périssables sont respectés. Les droits en cas de défaut demeurent.</p><p>Projet soumis à validation juridique.</p>'),
 ('fr','privacy','Confidentialité et données personnelles','Projet français concernant les données de compte, commande, paiement, support, sécurité et vérification vendeur.','# Confidentialité et données personnelles\n\nGolden Oremar peut traiter les données de compte, contact, livraison, commande, références de paiement, support, sécurité, notification et candidature producteur lorsqu elles sont nécessaires au service, aux obligations légales, à la prévention de la fraude et à la protection des droits. Les données complètes de carte ne sont pas destinées à être conservées dans la base Golden Oremar.\n\nL identité définitive du responsable du traitement et les transferts internationaux doivent être validés avant publication.','<h1>Confidentialité</h1><p>Golden Oremar traite les données nécessaires au fonctionnement de la place de marché, aux obligations légales et à la sécurité.</p><p>Version française provisoire, validation juridique requise.</p>'),
 ('fr','terms','Conditions d utilisation et de vente Golden Oremar','Projet français sur les vendeurs, informations produit, commandes, paiements, livraison et retours.','# Conditions d utilisation et de vente Golden Oremar\n\nGolden Oremar peut proposer des produits vendus par des producteurs indépendants et par la boutique officielle. L identité du vendeur, le stock, le prix, l origine, les exigences de livraison et les allégations particulières doivent provenir de données backend validées. Les paiements et reversements doivent rester traçables et ne pas créer de double règlement.\n\nCette version française est un projet de traduction soumis à validation juridique.','<h1>Conditions Golden Oremar</h1><p>Identité vendeur, exactitude produit, paiement, livraison et retours reposent sur des données validées et la loi applicable.</p><p>Projet soumis à validation juridique.</p>'),
 ('ku','about','Derbarê Golden Oremar de','Pêşnivîsa wergera Kurdî ya derbarê Golden Oremar, piştrastkirina hilberîneran û şefafiya bazarê.','# Derbarê Golden Oremar de\n\nGolden Oremar bazarek e ku hilberînerên gundî û herêmî bi xerîdaran re têkildar dike. Agahiyên derbarê hilber, esl, hilberîner, stok, nirx û şandinê divê ji daneyên rast û dikarin bên piştrastkirin werin. Îdîayên organîk, sertîfîka û nîşanên baweriyê bê belge nayên nîşandan.\n\nEv nivîs pêşnivîsa wergera Kurdî ye û berî weşandinê pêdivî bi kontrola qanûnî heye.','<h1>Derbarê Golden Oremar de</h1><p>Golden Oremar hilberînerên herêmî bi xerîdaran re dide hev û agahiyên rast û piştrastkirî dixwaze.</p><p>Ev werger pêşnivîs e û pêdivî bi kontrola qanûnî heye.</p>'),
 ('ku','returns','Vegera malê, paşvekişîn û hilberên bi pirsgirêk','Pêşnivîsa Kurdî ya mafê paşvekişînê, istîsnayên hilberên zû xerab dibin û mafên hilberên xerab.','# Vegera malê, paşvekişîn û hilberên bi pirsgirêk\n\nHeke istîsnayek qanûnî tune be, di firotina ji dûr de mafên paşvekişînê yên derbasdar tên parastin. Ji bo xwarinên zû xerab dibin, hilberên bi demê kurt û hin hilberên hijyenî yên vekirî dikare istîsna hebe. Ev istîsna mafên xerîdar ji bo hilberên şaş, kêm, zirardar an xerab ji holê ranake.\n\nEv pêşnivîsa wergerê ye û berî weşandinê divê were kontrol kirin.','<h1>Vegera malê û paşvekişîn</h1><p>Mafên qanûnî û istîsnayên derbasdar tên parastin. Mafên hilberên xerab dom dikin.</p><p>Pêşnivîs, kontrola qanûnî pêwîst e.</p>'),
 ('ku','privacy','Nepenî û daneyên kesane','Pêşnivîsa Kurdî ya daneyên hesab, ferman, dravdan, piştgirî, ewlehî û serlêdana hilberîner.','# Nepenî û daneyên kesane\n\nGolden Oremar dikare daneyên hesab, têkilî, navnîşan, ferman, referansa dravdanê, piştgirî, ewlehî, agahdarkirin û serlêdana hilberîner ji bo pêşkêşkirina karûbar, peywirên qanûnî, pêşîlêgirtina sextekariyê û parastina mafan bixebitîne. Daneyên kartê yên vekirî ji bo hilanînê di databasa Golden Oremar de nehatine sêwirandin.\n\nNasnameya dawî ya berpirsê daneyan û veguhastina navneteweyî berî weşandinê divê were kontrol kirin.','<h1>Nepenî û daneyên kesane</h1><p>Golden Oremar tenê daneyên pêwîst ji bo bazar, peywirên qanûnî û ewlehiyê dixebitîne.</p><p>Ev werger pêşnivîs e û pêdivî bi kontrola qanûnî heye.</p>'),
 ('ku','terms','Mercên bikaranînê yên Golden Oremar','Pêşnivîsa Kurdî ya rola firoşkar, rastiya hilberê, ferman, dravdan, şandin û vegerê.','# Mercên bikaranînê yên Golden Oremar\n\nLi Golden Oremar hem hilberînerên serbixwe hem jî dikana fermî ya Golden Oremar dikarin bifiroşin. Nasnameya firoşkar, stok, nirx, esl, şertên şandinê û îdîayên taybet divê ji daneyên backend ên piştrastkirî werin. Qeydên dravdan û dayîna para hilberîner divê şopbar bin û du caran dayîn çênekin.\n\nEv nivîs pêşnivîsa wergera Kurdî ye û berî weşandinê pêdivî bi kontrola qanûnî heye.','<h1>Mercên Golden Oremar</h1><p>Nasnameya firoşkar, rastiya hilberê, dravdan, şandin û veger li gor daneyên piştrastkirî û qanûna derbasdar tên rêvebirin.</p><p>Pêşnivîs, kontrola qanûnî pêwîst e.</p>'),
 ('ar','about','حول Golden Oremar','مسودة ترجمة عربية عن Golden Oremar والتحقق من المنتجين وشفافية السوق.','# حول Golden Oremar\n\nGolden Oremar منصة سوق تربط المنتجين القرويين والمحليين بالعملاء مع الحفاظ على معلومات واضحة عن المنتج والمنشأ والبائع والمخزون والشحن. لا تعرض ادعاءات العضوية أو الشهادات أو مؤشرات الثقة إلا عندما تستند إلى بيانات حقيقية قابلة للتحقق.\n\nهذه النسخة العربية مسودة ترجمة للنص التركي ويجب مراجعتها قانونيا قبل نشرها كنص ملزم.','<h1>حول Golden Oremar</h1><p>تربط Golden Oremar المنتجين المحليين بالعملاء مع اشتراط معلومات قابلة للتحقق عن المنتج والبائع.</p><p>هذه ترجمة مسودة وتحتاج إلى مراجعة قانونية نهائية.</p>'),
 ('ar','returns','الإرجاع والعدول والمنتجات المعيبة','مسودة عربية لسياسة العدول واستثناءات السلع سريعة التلف وحقوق المنتجات المعيبة.','# الإرجاع والعدول والمنتجات المعيبة\n\nعندما لا ينطبق استثناء قانوني، تحترم حقوق العدول المطبقة على البيع عن بعد. قد توجد استثناءات للسلع سريعة التلف والأغذية قصيرة الصلاحية وبعض المنتجات الصحية بعد فتحها. لا تلغي هذه الاستثناءات حقوق المستهلك المتعلقة بالمنتجات الخاطئة أو التالفة أو الناقصة أو المعيبة.\n\nهذا النص مسودة ترجمة ويجب مراجعته قانونيا قبل النشر.','<h1>الإرجاع والعدول</h1><p>تطبق حقوق العدول القانونية والاستثناءات المسموح بها للسلع سريعة التلف مع بقاء حقوق المنتجات المعيبة.</p><p>مسودة تحتاج إلى مراجعة قانونية.</p>'),
 ('ar','privacy','الخصوصية والبيانات الشخصية','مسودة عربية حول بيانات الحساب والطلب والدفع والدعم والأمان والتحقق من المنتجين.','# الخصوصية والبيانات الشخصية\n\nقد تعالج Golden Oremar بيانات الحساب والاتصال والتسليم والطلبات ومراجع الدفع والدعم والأمان والإشعارات وطلبات المنتجين بالقدر اللازم لتقديم الخدمة والالتزامات القانونية ومنع الاحتيال وحماية الحقوق. لم يصمم نظام Golden Oremar لتخزين بيانات البطاقة المصرفية الكاملة في قاعدة البيانات.\n\nيجب مراجعة الهوية النهائية لمسؤول البيانات وضمانات النقل الدولي قبل نشر هذه الترجمة.','<h1>الخصوصية والبيانات الشخصية</h1><p>تعالج Golden Oremar البيانات اللازمة لتشغيل السوق والالتزامات القانونية والأمان.</p><p>هذه النسخة العربية مسودة وتحتاج إلى مراجعة قانونية نهائية.</p>'),
 ('ar','terms','شروط استخدام وسوق Golden Oremar','مسودة عربية لأدوار البائعين ودقة المنتج والطلبات والدفع والتسليم والإرجاع.','# شروط استخدام وسوق Golden Oremar\n\nيمكن أن تعرض Golden Oremar منتجات يبيعها منتجون مستقلون أو متجر Golden Oremar الرسمي. يجب أن تأتي هوية البائع والمخزون والسعر والمنشأ ومتطلبات الشحن والادعاءات الخاصة من بيانات خلفية تم التحقق منها. يجب أن تبقى سجلات الدفع والتسوية قابلة للتتبع وألا تنشئ دفعا مزدوجا.\n\nهذه النسخة العربية مسودة ترجمة وتحتاج إلى مراجعة قانونية قبل النشر.','<h1>شروط Golden Oremar</h1><p>تعتمد هوية البائع ودقة المنتج والدفع والتسليم والإرجاع على بيانات سوق موثقة والقانون المطبق.</p><p>مسودة تحتاج إلى مراجعة قانونية.</p>')
)
insert into public.content_entries(
 id,content_type,slug,title,summary,body_markdown,body_html_sanitized,status,locale,translation_group_id,tags,metadata,seo,created_at,updated_at
)
select gen_random_uuid(),'legal',d.slug,d.title,d.summary,d.body_markdown,d.body_html,'draft',d.locale,s.id,array['legal','translation-draft']::text[],jsonb_build_object('managedBy','release_hardening_20260821','draftTranslation',true,'sourceLocale','tr','requiresLegalReview',true),jsonb_build_object('title',d.title,'description',d.summary),timezone('utc',now()),timezone('utc',now())
from drafts d join source s on s.slug=d.slug
on conflict(content_type,slug,locale) do nothing;
